UPDATE businesses SET description = 'Intermed Medical Practice is a healthcare practice located in the Sunnyfair Building at 171 Robert Sobukwe Street in Sunnyside, Pretoria. The practice is listed as a family medicine provider and serves patients looking for accessible medical care within the Pretoria central and Sunnyside area. Public healthcare directories identify Intermed Medical Practice as a medical facility offering family medicine services, with the practice having been associated with this address for several years. The facility is conveniently situated in a busy part of Pretoria and is accessible to residents, workers and visitors in the surrounding communities. Intermed Medical Practice is focused on providing professional medical attention in a convenient clinical environment, making it a practical option for individuals and families seeking general healthcare services. The practice is also listed as wheelchair accessible, with accessible parking and toilet facilities.', description_enriched_at = datetime('now') WHERE slug = 'intermed-medical-practice-pretoria-central' AND description = 'A family medicine practice in Trevenna.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
